from fastapi import APIRouter, Body, Depends

from modules.operationalNoticeTemplates import (
    all_operationalNoticeTemplates_sp, operationalNoticeTemplates_sp,
)
from security.session_tokens import require_platform_admin_session, require_staff_session_or_worker_key

# Generated by posgmo-factory (PRD tests/prd_operationalNoticeTemplate.json); guards added by hand.
# Platform library (no companyId): only a SmartLoans admin (companyId 1008) writes it; any staff reads it.
router = APIRouter()

with open("./docs_description/operationalNoticeTemplates.txt", "r", encoding="utf-8") as file:
    templates_docstring = file.read()
with open("./docs_description/operationalNoticeTemplates_all.txt", "r", encoding="utf-8") as file:
    templates_all_docstring = file.read()


@router.post("/operationalNoticeTemplates", summary="operationalNoticeTemplates: create / update / retire (platform admin)",
             description=templates_docstring, dependencies=[Depends(require_platform_admin_session)])
def operationalNoticeTemplates(json_file: dict = Body(...)):
    return operationalNoticeTemplates_sp(json_file)


@router.post("/all_operationalNoticeTemplates", summary="operational notice template library",
             description=templates_all_docstring, dependencies=[Depends(require_staff_session_or_worker_key)])
def all_operationalNoticeTemplates(json_file: dict = Body(default={})):
    return all_operationalNoticeTemplates_sp(json_file)
